import { test } from "node:test";
import assert from "node:assert/strict";
import { FALLBACK_TTL_MS, SURGE_TTL_MS, SurgeService, multiplierFrom, type ZoneDemand } from "../src/surge/surge.ts";
import { quoteFare } from "../src/surge/fares.ts";

function setup(maxZones?: number) {
    let now = Date.parse("2026-11-19T17:30:00Z");
    const demand = new Map<string, ZoneDemand>();
    const feed = {
        calls: 0,
        down: false,
        async current(zoneId: string) {
            this.calls++;
            if (this.down) throw new Error("feed unavailable");
            return demand.get(zoneId) ?? { openRequests: 0, availableDrivers: 10 };
        },
    };
    const surge = new SurgeService(feed, () => now, maxZones);
    return { feed, demand, surge, advance: (ms: number) => (now += ms) };
}

const trip = { zoneId: "downtown", distanceKm: 10, durationMin: 20 };

test("a computed multiplier is reused for 30 seconds", async () => {
    const { feed, demand, surge, advance } = setup();
    demand.set("downtown", { openRequests: 40, availableDrivers: 20 });
    assert.deepEqual(await surge.surgeFor("downtown"), { multiplier: 2, source: "live" });
    advance(SURGE_TTL_MS - 1);
    await surge.surgeFor("downtown");
    assert.equal(feed.calls, 1);
});

test("a busy zone is recomputed 30 seconds after the last computation, however often riders ask", async () => {
    const { feed, demand, surge, advance } = setup();
    demand.set("downtown", { openRequests: 50, availableDrivers: 20 });
    await surge.surgeFor("downtown");
    demand.set("downtown", { openRequests: 10, availableDrivers: 20 });
    for (let t = 0; t < 6; t++) {
        advance(5_000);
        await surge.surgeFor("downtown");
    }
    const after = await surge.surgeFor("downtown");
    console.log(`after 30s of riders asking every 5s: multiplier ${after.multiplier}, feed called ${feed.calls}x`);
    assert.equal(after.multiplier, 1);
    assert.equal(feed.calls, 2);
});

test("fare quotes drop back to normal once the rush is over", async () => {
    const { demand, surge, advance } = setup();
    demand.set("downtown", { openRequests: 60, availableDrivers: 20 });
    assert.equal((await quoteFare(surge, trip)).totalCents, 5350);
    demand.set("downtown", { openRequests: 5, availableDrivers: 20 });
    for (let t = 0; t < 20; t++) {
        advance(2_000);
        await quoteFare(surge, trip);
    }
    assert.deepEqual(await quoteFare(surge, trip), { zoneId: "downtown", baseCents: 1700, multiplier: 1, totalCents: 1950 });
});

test("after a feed outage the fallback is only used for 5 seconds", async () => {
    const { feed, demand, surge, advance } = setup();
    demand.set("airport", { openRequests: 30, availableDrivers: 10 });
    feed.down = true;
    assert.deepEqual(await surge.surgeFor("airport"), { multiplier: 1, source: "fallback" });
    feed.down = false;
    advance(2_000);
    assert.equal((await surge.surgeFor("airport")).source, "fallback");
    advance(2_000);
    await surge.surgeFor("airport");
    advance(FALLBACK_TTL_MS - 4_000);
    assert.deepEqual(await surge.surgeFor("airport"), { multiplier: 3, source: "live" });
});

test("only the most recently used zones are kept", async () => {
    const { feed, surge } = setup(2);
    await surge.surgeFor("a");
    await surge.surgeFor("b");
    await surge.surgeFor("a");
    await surge.surgeFor("c"); // evicts b, the least recently used
    assert.equal(feed.calls, 3);
    await surge.surgeFor("a");
    assert.equal(feed.calls, 3);
    await surge.surgeFor("b");
    assert.equal(feed.calls, 4);
});

test("multipliers are rounded to one decimal and capped at 3x", () => {
    assert.equal(multiplierFrom({ openRequests: 5, availableDrivers: 10 }), 1);
    assert.equal(multiplierFrom({ openRequests: 37, availableDrivers: 20 }), 1.9);
    assert.equal(multiplierFrom({ openRequests: 90, availableDrivers: 0 }), 3);
});

test("each zone is quoted with its own surge and the minimum fare applies", async () => {
    const { demand, surge } = setup();
    demand.set("stadium", { openRequests: 25, availableDrivers: 10 });
    assert.equal((await quoteFare(surge, { ...trip, zoneId: "stadium" })).totalCents, 4500);
    assert.equal((await quoteFare(surge, trip)).totalCents, 1950);
    assert.equal((await quoteFare(surge, { zoneId: "suburb", distanceKm: 1, durationMin: 3 })).totalCents, 700);
});
